const items = $input.all();
const output = [];

const SECTIONS = [
    'indications_and_usage',
    'dosage_and_administration',
    'dosage_forms_and_strengths',
    'contraindications',
    'warnings',
    'warnings_and_cautions',
    'boxed_warning',
    'adverse_reactions',
    'drug_interactions',
    'use_in_specific_populations',
    'pregnancy',
    'nursing_mothers',
    'pediatric_use',
    'geriatric_use',
    'overdosage',
    'mechanism_of_action',
    'patient_information'
];

const MAX_CHUNK_CHARS = 1500;
const OVERLAP_CHARS = 150;

function splitIntoChunks(text, maxLen, overlap) {
    if (text.length <= maxLen) return [text];
    const chunks = [];
    let start = 0;
    while (start < text.length) {
        let end = Math.min(start + maxLen, text.length);
        if (end < text.length) {
            const lastPeriod = text.lastIndexOf('. ', end);
            if (lastPeriod > start + maxLen / 2) {
                end = lastPeriod + 1;
            }
        }
        chunks.push(text.slice(start, end).trim());
        if (end >= text.length) break;
        start = end - overlap;
    }
    return chunks;
}

// =========================================================================
// PASS 1: Read all files into a map keyed by base drug name
// =========================================================================
// We process all items first because for each drug we have TWO files
// (e.g., amlodipine.json and amlodipine.meta.json) that need to be paired.

const drugFiles = {};   // { "amlodipine": { label: {...}, meta: {...} }, ... }

for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const filename = 
        item.binary?.data?.fileName 
        || item.json?.fileName
        || item.json?.data?.fileName
        || '';

    if (!filename) continue;
    if (filename.startsWith('_')) continue;  // skip _run_log.json

    // Determine base drug name and file type
    let baseName, fileType;
    if (filename.endsWith('.meta.json')) {
        baseName = filename.replace('.meta.json', '');
        fileType = 'meta';
    } else if (filename.endsWith('.json')) {
        baseName = filename.replace('.json', '');
        fileType = 'label';
    } else {
        continue;
    }

    // Read the file content
    let parsed;
    try {
        const binaryData = await this.helpers.getBinaryDataBuffer(i, 'data');
        const text = binaryData.toString('utf-8');
        parsed = JSON.parse(text);
    } catch (e) {
        console.log(`Failed to parse ${filename}: ${e.message}`);
        continue;
    }

    // Initialize the entry if not present
    if (!drugFiles[baseName]) {
        drugFiles[baseName] = { label: null, meta: null };
    }
    drugFiles[baseName][fileType] = parsed;
}

// =========================================================================
// PASS 2: For each drug, build chunks using BOTH label content and metadata
// =========================================================================

for (const [baseName, files] of Object.entries(drugFiles)) {
    if (!files.label) {
        console.log(`No label file for ${baseName}, skipping`);
        continue;
    }

    const label = files.label;
    const meta = files.meta || {};
    const openfda = label.openfda || {};

    // Prefer meta file's drug_query as canonical name (it's clean: "amlodipine")
    // Fall back to filename if meta is missing
    const drugName = (meta.drug_query || baseName.replace(/_/g, ' ')).toLowerCase().trim();

    // Pull rich metadata from BOTH files (meta file is authoritative when present)
    const brandNames = (meta.brand_names || openfda.brand_name || []).slice(0, 5);
    const genericNames = (meta.generic_names || openfda.generic_name || []).slice(0, 5);
    const manufacturers = (meta.manufacturer_names || openfda.manufacturer_name || []).slice(0, 3);
    const rxcuiList = (meta.rxcui || openfda.rxcui || []).slice(0, 10);
    const productType = (meta.product_type || openfda.product_type || []).join(', ');
    const route = (meta.route || openfda.route || []).join(', ');
    const splSetId = meta.spl_set_id || (openfda.spl_set_id || [])[0] || null;
    const effectiveTime = meta.effective_time || label.effective_time || null;

    for (const section of SECTIONS) {
        if (!label[section]) continue;

        const sectionText = Array.isArray(label[section])
            ? label[section].join('\n\n')
            : String(label[section]);

        if (!sectionText.trim()) continue;

        const chunks = splitIntoChunks(sectionText, MAX_CHUNK_CHARS, OVERLAP_CHARS);

        chunks.forEach((chunk, idx) => {
            const sectionLabel = section.replace(/_/g, ' ');
            const contextHeader = `[${drugName.toUpperCase()} - ${sectionLabel}]`;
            const fullChunk = `${contextHeader}\n${chunk}`;

            output.push({
                json: {
                    pageContent: fullChunk,
                    metadata: {
                        // Identity
                        drug_name: drugName,
                        section: section,
                        chunk_index: idx,
                        total_chunks_in_section: chunks.length,

                        // Names (useful for the Classifier and Tool Agent)
                        brand_names: brandNames.join(', '),
                        generic_names: genericNames.join(', '),
                        manufacturers: manufacturers.join(', '),

                        // Standard identifiers (useful for the Tool Agent
                        // when calling RxNorm or OpenFDA APIs)
                        rxcui: rxcuiList.join(', '),
                        spl_set_id: splSetId,

                        // Drug characteristics (useful for safety filtering)
                        product_type: productType,
                        route: route,

                        // Provenance (useful for the Response Agent's citations)
                        source: 'OpenFDA',
                        effective_time: effectiveTime
                    }
                }
            });
        });
    }
}

return output;
